    def component_count(color):
        remaining = set(positions[color])
        count = 0
        while remaining:
            count += 1
            stack = [remaining.pop()]
            while stack:
                r, c = stack.pop()
                for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if p in remaining:
                        remaining.remove(p)
                        stack.append(p)
        return count

    # Dots are numerous mutually disconnected copies' centers; template colors
    # form the compact source object.
    marker = max(positions, key=lambda color: (component_count(color), len(positions[color])))
    source = [(r, c) for color, cells in positions.items() if color != marker for r, c in cells]
    top, bottom = min(r for r, c in source), max(r for r, c in source)
    left, right = min(c for r, c in source), max(c for r, c in source)
    template = [row[left:right + 1] for row in grid[top:bottom + 1]]
    ar, ac = len(template) // 2, len(template[0]) // 2

    out = [row[:] for row in grid]
    for r, c in positions[marker]:
        for pr, row in enumerate(template):
            for pc, value in enumerate(row):
                y, x = r + pr - ar, c + pc - ac
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = value
    return out


